{
  "aggregate_id": "DEF-NRS-484B-018::electric_scooter",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "contradicted",
      "reason": "The required defined term “vehicle” expressly excepts devices moved by human power, matching this class's human-powered contract."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "The bus contract states passenger-carrying design but no minimum weight that makes the 100-pound limit impossible."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "A child pedestrian is a person rather than the vehicle with handlebars and an electric motor required by the definition."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract permits membership through commercial licensing alone and specifies no mass threshold establishing incompatibility with the 100-pound limit."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "contradicted",
      "reason": "The nested definition of “vehicle” expressly excepts electric bicycles, and the posted electric-bicycle definition also expressly disclaims electric scooters."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "contradicted",
      "reason": "The controlling definition requires a “vehicle,” but the posted definition of that required term expressly excepts an electric scooter."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "underdetermined",
      "reason": "Jurisdictional designation as an emergency vehicle establishes no minimum weight or other contractual incompatibility with the admitting requirements."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting-vehicle contract supplies no minimum weight that would establish the asserted incompatibility with the 100-pound limit."
    },
    {
      "class": "ru.moped",
      "verdict": "contradicted",
      "reason": "The posted moped definition expressly states that the term does not include an electric scooter, preventing the proposed overlap."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The self-propelled-vehicle contract does not settle the electric motor, handlebars, riding design, weight and speed requirements for this class."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The motorcycle contract specifies wheel count and astride riding but does not settle the required propulsion, weight or speed characteristics."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "underdetermined",
      "reason": "Official or contracted road service and identifying equipment impose no minimum weight that establishes the claimed incompatibility."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The pedestrian contract describes a person, not the vehicle that the controlling definition requires."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian with specified assistance, not a vehicle with handlebars and an electric motor."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The on-track-equipment contract establishes neither a minimum weight nor exclusive use upon stationary rails, so neither the weight cap nor the nested rail exception rules out every member."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "The school-bus contract specifies passenger purpose and markings but no minimum weight that establishes failure of the 100-pound limit."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "The passenger-for-hire contract and identifying markings establish no minimum weight or other necessary failure of the definition's requirements."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Neither branch of the contract states a minimum weight that establishes the asserted incompatibility with the 100-pound limit."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "The contract includes combinations and does not establish that every member necessarily lacks propulsion from its electric motor or rider."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public transit service and identifying livery or route displays establish no minimum weight that makes the 100-pound limit impossible."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A goods-carrying body and motor-vehicle design establish no minimum weight that rules out every member under the posted limit."
    }
  ]
}

